// Shared helpers for listening audio: resolve pre-generated studio narration
// files (public/audio/listening/<sha1>.mp3, generated by
// scripts/generate_listening_audio.cjs) and build graceful device-voice
// fallbacks for dynamic scripts (teacher-created assignments) that have no
// bundled audio.
//
// The hash contract MUST match the generator:
//   key = script.replace(/\s+/g, ' ').trim()  ->  sha1 hex of UTF-8 bytes.
// If the script text is ever edited, the hash changes and the player falls
// back to the device voice until audio is regenerated — audio never lies.

export interface SpeechTurn {
  speaker: string | null;
  text: string;
}

export function normalizeScriptKey(text: string): string {
  return text.replace(/\s+/g, ' ').trim();
}

async function sha1Hex(text: string): Promise<string> {
  const data = new TextEncoder().encode(text);
  const buf = await crypto.subtle.digest('SHA-1', data);
  return Array.from(new Uint8Array(buf))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

function audioBase(): string | null {
  if (typeof document === 'undefined') return null;
  try {
    return new URL('audio/listening/', document.baseURI).href;
  } catch {
    return null;
  }
}

type Manifest = Record<string, { file: string; title?: string; seconds?: number }>;

let manifestPromise: Promise<Manifest> | null = null;

function loadManifest(): Promise<Manifest> {
  if (!manifestPromise) {
    const base = audioBase();
    manifestPromise = base
      ? fetch(new URL('manifest.json', base).href)
          .then((r) => (r.ok ? (r.json() as Promise<Manifest>) : {}))
          .catch(() => ({} as Manifest))
      : Promise.resolve({});
  }
  return manifestPromise;
}

/**
 * Resolve a listening script to a bundled narration file, or null when the
 * script has no pre-generated audio (dynamic/teacher-created content).
 */
export async function resolveListeningAudio(script: string): Promise<string | null> {
  if (typeof crypto === 'undefined' || !crypto.subtle || !audioBase()) return null;
  if (!script.trim()) return null;
  try {
    const hash = await sha1Hex(normalizeScriptKey(script));
    const manifest = await loadManifest();
    const entry = manifest[hash];
    if (!entry?.file) return null;
    return new URL(entry.file, document.baseURI).href;
  } catch {
    return null;
  }
}

/**
 * Split a "Speaker: text" transcript into turns so the device-voice fallback
 * can strip labels (never read "Maya:" aloud) and alternate pitch between
 * speakers for a more natural feel.
 */
export function splitSpeechTurns(script: string): SpeechTurn[] {
  const clean = script.replace(/\s+/g, ' ').trim();
  if (!clean) return [];
  const parts = clean.split(/(?=(?:^|\s)[A-Z][A-Za-z]{2,12}: )/g).map((s) => s.trim()).filter(Boolean);
  const turns: SpeechTurn[] = [];
  for (const part of parts) {
    const m = part.match(/^([A-Z][A-Za-z]{2,12}):\s*(.*)$/);
    if (m) turns.push({ speaker: m[1], text: m[2] });
    else if (turns.length > 0) turns[turns.length - 1].text += ` ${part}`;
    else turns.push({ speaker: null, text: part });
  }
  return turns;
}
